using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        "RegionEncoded",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label",
        featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

var predictions = model.Transform(split.TestSet);
try
{
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Model trained — test set too small for full metrics; add more data for reliable evaluation.");
}

builder.Services.AddSingleton(mlContext);
builder.Services.AddSingleton(model);
builder.Services.AddSingleton(new Microsoft.Extensions.ObjectPool.DefaultObjectPoolProvider()
    .Create(new PredictionEnginePoolPolicy(mlContext, model)));

var app = builder.Build();

app.MapPost("/predict", (Microsoft.Extensions.ObjectPool.ObjectPool<PredictionEngine<CustomerData, ChurnPrediction>> pool, CustomerData customer) =>
{
    var engine = pool.Get();
    try
    {
        var prediction = engine.Predict(customer);
        return Results.Ok(new
        {
            WillChurn = prediction.PredictedLabel,
            Probability = prediction.Probability,
            Score = prediction.Score
        });
    }
    finally
    {
        pool.Return(engine);
    }
});

app.Run();

public class PredictionEnginePoolPolicy(MLContext mlContext, ITransformer model)
    : Microsoft.Extensions.ObjectPool.IPooledObjectPolicy<PredictionEngine<CustomerData, ChurnPrediction>>
{
    public PredictionEngine<CustomerData, ChurnPrediction> Create() =>
        mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);

    public bool Return(PredictionEngine<CustomerData, ChurnPrediction> obj) => true;
}

